('JK-920D', 'N2', '鈍', 271, 'Độn', '[]', 'cùn; chậm; ngu ngốc', '["ドン"]', '["にぶ.い","にぶ.る","にぶ-","なま.る","なまく.ら"]', '["どん","にぶ.い"]', 'LEVEL_WORDS', 12, 167, 'kim', NULL, 'KIM (金) loại ở bên trái cùng chữ ĐỒN (屯) đóng quân dậm chân tại chỗ: lưỡi dao bị cùn, chậm chạp, ĐỘN.', NULL, 'AI_CHECKED', 1, 'd667dcc546cf'),
('JK-9271', 'N2', '鉱', 247, 'Khoáng', '[]', 'khoáng sản; quặng', '["コウ"]', '["あらがね"]', '["こう"]', 'LEVEL_WORDS', 13, 167, 'kim', NULL, 'KIM (金) loại ở bên trái, bên phải là chữ quảng (広) rộng lớn: kim loại nằm trong lòng đất rộng, đó là KHOÁNG sản.', NULL, 'AI_CHECKED', 1, 'd667dcc546cf'),
('JK-9285', 'N2', '銅', 212, 'Đồng', '[]', 'đồng', '["ドウ"]', '["あかがね"]', '["どう"]', 'LEVEL_WORDS', 14, 167, 'kim', NULL, 'Kim loại 金 cùng loại với 同 nhau, cùng màu đỏ: ĐỒNG (銅) là kim loại đồng.', NULL, 'AI_CHECKED', 1, 'd667dcc546cf'),
('JK-92ED', 'N2', '鋭', 241, 'Duệ', '["Nhuệ"]', 'nhọn; sắc bén; cạnh', '["エイ"]', '["するど.い"]', '["するど.い"]', 'LEVEL_WORDS', 15, 167, 'kim', NULL, 'Bên trái là KIM (金) loại kim loại, bên phải là ĐOÀI (兑) như người há miệng cười lộ răng; mài kim loại cho thật bén thì lưỡi dao sắc bén (DUỆ).', NULL, 'AI_CHECKED', 1, 'd667dcc546cf'),
('JK-9332', 'N2', '録', 161, 'Lục', '[]', 'ghi chép', '["ロク"]', '["しる.す","と.る"]', '["ろく"]', 'LEVEL_WORDS', 16, 167, 'kim', NULL, 'Kim loại 金 khắc chữ thành bản khắc để ghi lại điều đã xảy ra: LỤC (録) là ghi chép, ghi âm.', NULL, 'AI_CHECKED', 1, 'd667dcc546cf'),
('JK-9632', 'N2', '防', 99, 'Phòng', '[]', 'ngăn chặn; bảo vệ; chống lại', '["ボウ"]', '["ふせ.ぐ"]', '["ぼう","ふせ.ぐ"]', 'LEVEL_WORDS', 7, 170, 'phụ', NULL, 'Gò đất (阝) kè cạnh phía vuông (方): xây bờ đê chắn đường nước để PHÒNG ngừa lũ.', NULL, 'AI_CHECKED', 1, 'd667dcc546cf'),
('JK-9678', 'N2', '陸', 184, 'Lục', '[]', 'đất liền; sáu', '["リク","ロク"]', '["おか"]', '["りく"]', 'LEVEL_WORDS', 11, 170, 'phụ', NULL, 'Gò đất 阝 cao, nhiều tầng đất chồng lên nhau, đứng trên nhìn thấy đất liền: LỤC (陸) là lục địa.', NULL, 'AI_CHECKED', 1, 'd667dcc546cf'),
('JK-9685', 'N2', '隅', 298, 'Ngung', '[]', 'góc; ngách', '["グウ"]', '["すみ"]', '["すみ"]', 'LEVEL_WORDS', 12, 170, 'phụ', NULL, 'Bên trái là gò đất (阝), bên phải là chữ NGU (禺) con khỉ nhỏ: con khỉ trốn vào góc đồi, góc kẹt, NGUNG.', NULL, 'AI_CHECKED', 1, 'd667dcc546cf'),
('JK-96BB', 'N2', '隻', 299, 'Chích', '[]', 'một chiếc; đơn vị đếm tàu thuyền', '["セキ"]', '[]', '[]', NULL, 10, 172, 'chuy', NULL, 'Một con chim (隹) đứng yên bên cạnh nữa, rồi đến một chiếc thuyền mới: đếm tàu thuyền bằng CHÍCH, từng chiếc.', NULL, 'AI_CHECKED', 1, 'd667dcc546cf'),
('JK-96C7', 'N2', '雇', 237, 'Cố', '[]', 'thuê; mướn', '["コ"]', '["やと.う"]', '["こ","やと.う"]', 'LEVEL_WORDS', 12, 172, 'chuy', NULL, 'Chim 隹 bên dưới cánh cửa 戸: chủ nhà thuê người, giữ lại làm việc: CỐ (雇) là thuê, mướn.', NULL, 'AI_CHECKED', 1, 'd667dcc546cf'),
('JK-96F2', 'N2', '雲', 27, 'Vân', '[]', 'mây', '["ウン"]', '["くも","-ぐも"]', '["くも","-ぐも"]', 'LEVEL_WORDS', 12, 173, 'vũ', NULL, 'Bên dưới mưa (雨) là chữ 云 giống làn khói cuộn lên; khi hơi nước cuộn lên trời sẽ thành đám VÂN, mây.', NULL, 'AI_CHECKED', 1, 'd667dcc546cf'),
('JK-96F6', 'N2', '零', 273, 'Linh', '[]', 'số không; rơi rụng; lẻ', '["レイ"]', '["ぜろ","こぼ.す","こぼ.れる"]', '["れい","こぼ.す","こぼ.れる"]', 'LEVEL_WORDS', 13, 173, 'vũ', NULL, 'MƯA (雨) rơi đến lúc chỉ còn từng giọt lẻ tẻ rồi tắt hẳn: còn lại số không, LINH, rơi rụng.', NULL, 'AI_CHECKED', 1, 'd667dcc546cf'),
('JK-9769', 'N2', '革', 114, 'Cách', '["Cức"]', 'da; cải cách; da thuộc', '["カク"]', '["かわ"]', '["かく","かわ"]', 'LEVEL_WORDS', 9, 177, 'cách', NULL, 'Tấm da thú căng ra, thả đầu và đuôi, rồi phơi cho khô và thuộc: CÁCH là da thuộc, và cũng là cải cách.', NULL, 'AI_CHECKED', 1, 'd667dcc546cf'),
('JK-9810', 'N2', '預', 173, 'Dự', '[]', 'gửi; ủy thác; giữ hộ', '["ヨ"]', '["あず.ける","あず.かる"]', '["よ","あず.ける","あず.かる"]', 'LEVEL_WORDS', 13, 181, 'hiệt', NULL, 'Tôi giao 予 trước cho người khác giữ lại cái đầu 頁 của món đồ: DỰ (預) là gửi giữ, ủy thác.', NULL, 'AI_CHECKED', 1, 'd667dcc546cf'),
('JK-9818', 'N2', '領', 110, 'Lĩnh', '[]', 'quyền hạn; lãnh thổ; lãnh địa', '["リョウ"]', '["えり"]', '["りょう"]', 'LEVEL_WORDS', 14, 181, 'hiệt', NULL, 'Ra lệnh (令) cho cái đầu (頁) đứng đầu một vùng đất: người lãnh đạo coi giữ lãnh thổ, LĨNH.', NULL, 'AI_CHECKED', 1, 'd667dcc546cf'),
('JK-9837', 'N2', '頷', 304, 'HẠM', '[]', 'gật đầu; cằm', '[]', '[]', '[]', NULL, NULL, NULL, NULL, NULL, 'Bên trái là chữ (含) ngậm, bên phải là cái đầu (頁): cúi đầu thấp xuống một cái là gật đầu, đồng ý.', NULL, 'AI_CHECKED', 1, 'd667dcc546cf'),
('JK-984D', 'N2', '額', 119, 'Ngạch', '[]', 'trán; bảng; bức tranh đóng khung', '["ガク"]', '["ひたい"]', '["がく","ひたい"]', 'LEVEL_WORDS', 18, 181, 'hiệt', NULL, 'Khách (客) đứng trước cái đầu (頁) có trán rộng: phần trán là NGẠCH, cũng là tấm bảng treo.', NULL, 'AI_CHECKED', 1, 'd667dcc546cf'),
('JK-9999', 'N2', '香', 229, 'Hương', '[]', 'hương; mùi; nước hoa', '["コウ","キョウ"]', '["か","かお.り","かお.る"]', '["こう","かお.り"]', 'LEVEL_WORDS', 9, 186, 'hương', NULL, 'Cây lúa 禾 chín vàng dưới ánh mặt trời 日 tỏa mùi thơm ngát: HƯƠNG (香) là mùi thơm, hương thơm.', NULL, 'AI_CHECKED', 1, 'd667dcc546cf'),
('JK-9AA8', 'N2', '骨', 62, 'Cốt', '[]', 'bộ xương; xương; hài cốt', '["コツ"]', '["ほね"]', '["こつ","ほね"]', 'LEVEL_WORDS', 10, 188, 'cốt', NULL, 'Phần thịt (月) bám quanh xương, phía trên là những đốt xương nối nhau như cái khớp: CỐT là xương.', NULL, 'AI_CHECKED', 1, 'd667dcc546cf'),
('JK-9EA6', 'N2', '麦', 18, 'Mạch', '[]', 'lúa mạch; lúa mì', '["バク"]', '["むぎ"]', '["むぎ"]', 'LEVEL_WORDS', 7, 199, 'mạch', NULL, 'Cây lúa có bông rũ xuống, phía dưới là rễ chân (夊): cây lúa mạch mọc ở ruộng khô, MẠCH.', NULL, 'AI_CHECKED', 1, 'd667dcc546cf'),
('JK-9EC4', 'N2', '黄', 25, 'Hoàng', '[]', 'màu vàng', '["コウ","オウ"]', '["き","こ-"]', '["き"]', 'LEVEL_WORDS', 11, 201, 'hoàng', NULL, 'Cánh đồng (田) sáng rực dưới ánh nắng, trên có mầm cỏ chín vàng: cả cánh đồng lúa một màu HOÀNG.', NULL, 'AI_CHECKED', 1, 'd667dcc546cf'),
('JK-9F3B', 'N2', '鼻', 75, 'Tị', '[]', 'mũi; mõm', '["ビ"]', '["はな"]', '["び","はな"]', 'LEVEL_WORDS', 14, 209, 'tị', NULL, 'Tự (自) mình đưa ra phía trước, ngoài trên mặt, rồi đặt thêm cái bình (畀) thở ra hít vào: TỊ là cái mũi.', NULL, 'AI_CHECKED', 1, 'd667dcc546cf'),
('JK-9F62', 'N2', '齢', 231, 'Linh', '[]', 'tuổi', '["レイ"]', '["よわい","とし"]', '["れい"]', 'LEVEL_WORDS', 17, 211, 'xỉ', NULL, 'Hàm răng 歯 ghép thêm lệnh 令 sắp xếp theo thứ tự: LINH (齢) là tuổi, số tuổi tính bằng răng.', NULL, 'AI_CHECKED', 1, 'd667dcc546cf'),
('JK-9F67', 'N2', '齧', 305, 'KHIẾT', '["NIẾT"]', 'gặm; cắn', '[]', '[]', '[]', NULL, NULL, NULL, NULL, NULL, 'Hàng răng (歯) nhai nghiến dưới phần chữ khế (契) khắc sâu: răng cắn gặm nhấm từng chút, gặm.', NULL, 'AI_CHECKED', 1, 'd667dcc546cf')
