('JG-bf620ebf50-O01', 'JG-bf620ebf50', 'N2', 'ORDER', 'ORDER', 1, '係員に / ご利用の / お声がけください。 / 際に', NULL, NULL, NULL, '["係員に","ご利用の","お声がけください。","際に"]', '[1,3,0,2]', NULL, NULL, 'Khi sử dụng, xin hãy gọi nhân viên.', 'AI_CHECKED', 1, 'd667dcc546cf'),
('JG-bf620ebf50-O02', 'JG-bf620ebf50', 'N2', 'ORDER', 'ORDER', 2, '必要書類を / 申し込みの / ご提出ください。 / 際に', NULL, NULL, NULL, '["必要書類を","申し込みの","ご提出ください。","際に"]', '[1,3,0,2]', NULL, NULL, 'Khi đăng ký, xin hãy nộp giấy tờ cần thiết.', 'AI_CHECKED', 1, 'd667dcc546cf'),
